// Enhanced Chicken Road Game
// A polished Crossy Road-style game with animations, sound effects, and power-ups
// Tailwind CSS required for styling

import React, { useEffect, useRef, useState, useCallback } from "react";

// CONFIG
const TILE_SIZE = 60; // Increased size for better visibility
const COLUMNS = 9; // horizontal tiles
const ROWS = 15; // Increased rows for longer gameplay
const INITIAL_PLAYER_COL = Math.floor(COLUMNS / 2);
const INITIAL_PLAYER_ROW = ROWS - 1; // bottom row

// Lane types
const LANE_SAFE = "safe"; // sidewalk
const LANE_ROAD = "road"; // cars move
const LANE_RIVER = "river"; // logs float
const LANE_TRAIN = "train"; // fast moving trains
const LANE_COLLECTIBLE = "collectible"; // coins and power-ups

// Enhanced lane definitions with more variety
const LANES = [
  { type: LANE_SAFE },
  { type: LANE_COLLECTIBLE, speed: 0, direction: 0, density: 0.3 }, // Coins
  { type: LANE_ROAD, speed: 1.2, direction: 1, density: 0.15 },
  { type: LANE_ROAD, speed: 0.9, direction: -1, density: 0.12 },
  { type: LANE_SAFE },
  { type: LANE_RIVER, speed: 1.0, direction: -1, density: 0.14 },
  { type: LANE_RIVER, speed: 0.7, direction: 1, density: 0.10 },
  { type: LANE_SAFE },
  { type: LANE_TRAIN, speed: 2.0, direction: 1, density: 0.08 }, // Fast trains
  { type: LANE_ROAD, speed: 1.4, direction: 1, density: 0.14 },
  { type: LANE_ROAD, speed: 1.0, direction: -1, density: 0.10 },
  { type: LANE_SAFE },
  { type: LANE_RIVER, speed: 0.8, direction: 1, density: 0.08 },
  { type: LANE_TRAIN, speed: 1.8, direction: -1, density: 0.06 },
  { type: LANE_SAFE }
];

// Power-up types
const POWERUP_SHIELD = "shield";
const POWERUP_SPEED = "speed";
const POWERUP_MAGNET = "magnet";

// Game states
const GAME_STATE_MENU = "menu";
const GAME_STATE_PLAYING = "playing";
const GAME_STATE_PAUSED = "paused";
const GAME_STATE_GAME_OVER = "gameOver";

// Helpers
function randBetween(a, b) {
  return Math.random() * (b - a) + a;
}

function createObstaclesForLane(laneIndex, density, laneType) {
  const objs = [];

  if (laneType === LANE_COLLECTIBLE) {
    // Create coins and power-ups
    for (let col = 0; col < COLUMNS; col++) {
      if (Math.random() < density) {
        const type = Math.random() < 0.8 ? "coin" : 
                    Math.random() < 0.5 ? POWERUP_SHIELD : 
                    Math.random() < 0.5 ? POWERUP_SPEED : POWERUP_MAGNET;
        objs.push({ x: col, width: 1, type });
      }
    }
  } else {
    // Create obstacles (cars, logs, trains)
    for (let col = 0; col < COLUMNS; col++) {
      if (Math.random() < density) {
        const width = laneType === LANE_TRAIN ? 3 : Math.random() < 0.5 ? 1 : 2;
        objs.push({ x: col, width, type: laneType });
        col += width - 1; // skip ahead to avoid overlap
      }
    }
  }
  return objs;
}

// Sound effects (using Web Audio API)
class SoundManager {
  constructor() {
    this.audioContext = null;
    this.sounds = {};
    this.init();
  }

  init() {
    try {
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
    } catch (e) {
      console.log("Web Audio API not supported");
    }
  }

  playTone(frequency, duration, type = "sine") {
    if (!this.audioContext) return;

    const oscillator = this.audioContext.createOscillator();
    const gainNode = this.audioContext.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(this.audioContext.destination);

    oscillator.frequency.value = frequency;
    oscillator.type = type;

    gainNode.gain.setValueAtTime(0.1, this.audioContext.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + duration);

    oscillator.start(this.audioContext.currentTime);
    oscillator.stop(this.audioContext.currentTime + duration);
  }

  playCoin() {
    this.playTone(800, 0.1, "square");
  }

  playPowerUp() {
    this.playTone(600, 0.2, "sine");
    setTimeout(() => this.playTone(800, 0.2, "sine"), 100);
  }

  playGameOver() {
    this.playTone(200, 0.5, "sawtooth");
  }

  playMove() {
    this.playTone(400, 0.05, "triangle");
  }
}

export default function ChickenRoadGame() {
  const [player, setPlayer] = useState({ col: INITIAL_PLAYER_COL, row: INITIAL_PLAYER_ROW });
  const [obstacles, setObstacles] = useState(() => {
    return LANES.map((lane, idx) => 
      (lane.type === LANE_ROAD || lane.type === LANE_RIVER || lane.type === LANE_TRAIN || lane.type === LANE_COLLECTIBLE) 
        ? createObstaclesForLane(idx, lane.density || 0.12, lane.type) 
        : []
    );
  });
  const [score, setScore] = useState(0);
  const [coins, setCoins] = useState(0);
  const [gameState, setGameState] = useState(GAME_STATE_MENU);
  const [powerUps, setPowerUps] = useState({
    shield: 0,
    speed: 0,
    magnet: 0
  });
  const [playerEffects, setPlayerEffects] = useState({
    shielded: false,
    speedBoost: false,
    magnetActive: false
  });
  const [highScore, setHighScore] = useState(() => 
    parseInt(localStorage.getItem('chickenRoadHighScore') || '0')
  );

  const lastUpdateRef = useRef(performance.now());
  const requestRef = useRef();
  const containerRef = useRef(null);
  const soundManager = useRef(new SoundManager());

  // Move player (grid-based)
  const movePlayer = useCallback((dcol, drow) => {
    if (gameState !== GAME_STATE_PLAYING) return;

    setPlayer(prev => {
      const nc = Math.max(0, Math.min(COLUMNS - 1, prev.col + dcol));
      const nr = Math.max(0, Math.min(ROWS - 1, prev.row + drow));

      // Score increases when player moves forward (upwards, row decreases)
      if (nr < prev.row) {
        setScore(s => s + 1);
        soundManager.current.playMove();
      }

      return { col: nc, row: nr };
    });
  }, [gameState]);

  // Start game
  const startGame = useCallback(() => {
    setGameState(GAME_STATE_PLAYING);
    setPlayer({ col: INITIAL_PLAYER_COL, row: INITIAL_PLAYER_ROW });
    setObstacles(LANES.map((lane, idx) => 
      (lane.type === LANE_ROAD || lane.type === LANE_RIVER || lane.type === LANE_TRAIN || lane.type === LANE_COLLECTIBLE) 
        ? createObstaclesForLane(idx, lane.density || 0.12, lane.type) 
        : []
    ));
    setScore(0);
    setCoins(0);
    setPlayerEffects({
      shielded: false,
      speedBoost: false,
      magnetActive: false
    });
    lastUpdateRef.current = performance.now();
  }, []);

  // Restart game
  const restart = useCallback(() => {
    startGame();
  }, [startGame]);

  // Pause/Resume game
  const togglePause = useCallback(() => {
    setGameState(prev => 
      prev === GAME_STATE_PLAYING ? GAME_STATE_PAUSED : GAME_STATE_PLAYING
    );
  }, []);

  // Game over
  const gameOver = useCallback(() => {
    setGameState(GAME_STATE_GAME_OVER);
    soundManager.current.playGameOver();

    // Update high score
    setHighScore(prev => {
      if (score > prev) {
        localStorage.setItem('chickenRoadHighScore', score.toString());
        return score;
      }
      return prev;
    });
  }, [score]);

  // Input handlers
  useEffect(() => {
    function onKey(e) {
      if (gameState === GAME_STATE_MENU) {
        if (e.key === "Enter" || e.key === " ") {
          startGame();
          e.preventDefault();
        }
        return;
      }

      if (gameState !== GAME_STATE_PLAYING) return;

      if (e.key === "ArrowUp" || e.key === "w") movePlayer(0, -1);
      if (e.key === "ArrowDown" || e.key === "s") movePlayer(0, 1);
      if (e.key === "ArrowLeft" || e.key === "a") movePlayer(-1, 0);
      if (e.key === "ArrowRight" || e.key === "d") movePlayer(1, 0);
      if (e.key === " ") {
        togglePause();
        e.preventDefault();
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [gameState, movePlayer, startGame, togglePause]);

  // Touch: simple on-screen buttons
  const handleTouchMove = useCallback((dir) => {
    if (gameState !== GAME_STATE_PLAYING) return;

    switch (dir) {
      case "up":
        movePlayer(0, -1);
        break;
      case "down":
        movePlayer(0, 1);
        break;
      case "left":
        movePlayer(-1, 0);
        break;
      case "right":
        movePlayer(1, 0);
        break;
      default:
        break;
    }
  }, [gameState, movePlayer]);

  // Game loop: move obstacles and check collisions
  useEffect(() => {
    function step(now) {
      const dt = Math.min(40, now - lastUpdateRef.current); // ms
      lastUpdateRef.current = now;
      if (gameState === GAME_STATE_PLAYING) {
        setObstacles(prevObs => {
          const next = prevObs.map((laneObs, r) => {
            const laneCfg = LANES[r];
            if (!laneCfg || (laneCfg.type !== LANE_ROAD && laneCfg.type !== LANE_RIVER && laneCfg.type !== LANE_TRAIN && laneCfg.type !== LANE_COLLECTIBLE)) {
              return laneObs;
            }

            const speed = laneCfg.speed || 1;
            const dir = laneCfg.direction || 1;

            // Move each obstacle
            const moved = laneObs.map(o => ({ ...o, x: o.x + (dir * speed * dt) / 100 }));

            // Recycle obstacles when they leave the visible grid
            const recycled = moved.map(o => {
              // if moving right and off-screen to the right
              if (dir > 0 && o.x > COLUMNS + 2) {
                if (laneCfg.type === LANE_COLLECTIBLE) {
                  const type = Math.random() < 0.8 ? "coin" : 
                              Math.random() < 0.5 ? POWERUP_SHIELD : 
                              Math.random() < 0.5 ? POWERUP_SPEED : POWERUP_MAGNET;
                  return { ...o, x: -2 - Math.random() * 2, width: 1, type };
                } else {
                  const width = laneCfg.type === LANE_TRAIN ? 3 : Math.random() < 0.5 ? 1 : 2;
                  return { ...o, x: -2 - Math.random() * 2, width, type: laneCfg.type };
                }
              }
              if (dir < 0 && o.x < -3) {
                if (laneCfg.type === LANE_COLLECTIBLE) {
                  const type = Math.random() < 0.8 ? "coin" : 
                              Math.random() < 0.5 ? POWERUP_SHIELD : 
                              Math.random() < 0.5 ? POWERUP_SPEED : POWERUP_MAGNET;
                  return { ...o, x: COLUMNS + Math.random() * 2, width: 1, type };
                } else {
                  const width = laneCfg.type === LANE_TRAIN ? 3 : Math.random() < 0.5 ? 1 : 2;
                  return { ...o, x: COLUMNS + Math.random() * 2, width, type: laneCfg.type };
                }
              }
              return o;
            });

            // Occasional random spawn
            if (Math.random() < (laneCfg.density || 0.12) * (dt / 5000)) {
              if (laneCfg.type === LANE_COLLECTIBLE) {
                const type = Math.random() < 0.8 ? "coin" : 
                            Math.random() < 0.5 ? POWERUP_SHIELD : 
                            Math.random() < 0.5 ? POWERUP_SPEED : POWERUP_MAGNET;
                recycled.push({ x: dir > 0 ? -2 : COLUMNS + Math.random(), width: 1, type });
              } else {
                const width = laneCfg.type === LANE_TRAIN ? 3 : Math.random() < 0.6 ? 1 : 2;
                recycled.push({ x: dir > 0 ? -2 : COLUMNS + Math.random(), width, type: laneCfg.type });
              }
            }
            return recycled;
          });

          return next;
        });

        // Collision checks
        setPlayer(prev => {
          const row = prev.row;
          const laneCfg = LANES[row];
          if (!laneCfg) return prev;

          const laneObs = obstacles[row] || [];

          if (laneCfg.type === LANE_COLLECTIBLE) {
            // Check for collectibles (coins and power-ups)
            for (let i = laneObs.length - 1; i >= 0; i--) {
              const o = laneObs[i];
              if (prev.col + 0.2 < o.x + o.width && prev.col + 0.8 > o.x) {
                // Collect item
                if (o.type === "coin") {
                  setCoins(c => c + 1);
                  soundManager.current.playCoin();
                } else if (o.type === POWERUP_SHIELD) {
                  setPowerUps(p => ({ ...p, shield: p.shield + 1 }));
                  setPlayerEffects(e => ({ ...e, shielded: true }));
                  soundManager.current.playPowerUp();
                  // Shield lasts for 5 seconds
                  setTimeout(() => {
                    setPlayerEffects(e => ({ ...e, shielded: false }));
                  }, 5000);
                } else if (o.type === POWERUP_SPEED) {
                  setPowerUps(p => ({ ...p, speed: p.speed + 1 }));
                  setPlayerEffects(e => ({ ...e, speedBoost: true }));
                  soundManager.current.playPowerUp();
                  // Speed boost lasts for 3 seconds
                  setTimeout(() => {
                    setPlayerEffects(e => ({ ...e, speedBoost: false }));
                  }, 3000);
                } else if (o.type === POWERUP_MAGNET) {
                  setPowerUps(p => ({ ...p, magnet: p.magnet + 1 }));
                  setPlayerEffects(e => ({ ...e, magnetActive: true }));
                  soundManager.current.playPowerUp();
                  // Magnet lasts for 4 seconds
                  setTimeout(() => {
                    setPlayerEffects(e => ({ ...e, magnetActive: false }));
                  }, 4000);
                }

                // Remove collected item
                setObstacles(prevObs => {
                  const newObs = [...prevObs];
                  newObs[row] = laneObs.filter((_, idx) => idx !== i);
                  return newObs;
                });
              }
            }
          } else if (laneCfg.type === LANE_ROAD || laneCfg.type === LANE_TRAIN) {
            // Check for vehicle collisions
            for (const o of laneObs) {
              const left = o.x;
              const right = o.x + o.width;
              if (prev.col + 0.2 < right && prev.col + 0.8 > left) {
                // Check if player has shield
                if (playerEffects.shielded) {
                  // Shield protects from one collision
                  setPlayerEffects(e => ({ ...e, shielded: false }));
                  soundManager.current.playPowerUp(); // Shield break sound
                  return prev;
                } else {
                  // collision -> game over
                  gameOver();
                  return prev;
                }
              }
            }
          } else if (laneCfg.type === LANE_RIVER) {
            // require player to be on a log, otherwise drown
            let onLog = false;
            for (const o of laneObs) {
              if (prev.col + 0.2 < o.x + o.width && prev.col + 0.8 > o.x) {
                // player on log -> move player with log
                onLog = true;
                const dir = laneCfg.direction || 1;
                const move = (dir * laneCfg.speed * (dt / 100));
                const newCol = prev.col + move;
                // clamp inside grid
                const clamped = Math.max(0, Math.min(COLUMNS - 1, newCol));
                // apply movement instantly to player
                prev = { col: clamped, row: prev.row };
                break;
              }
            }
            if (!onLog) {
              // Check if player has shield
              if (playerEffects.shielded) {
                setPlayerEffects(e => ({ ...e, shielded: false }));
                soundManager.current.playPowerUp();
                return prev;
              } else {
                // drown -> game over
                gameOver();
                return prev;
              }
            }
          }
          return prev;
        });
      }

      requestRef.current = requestAnimationFrame(step);
    }
    requestRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(requestRef.current);
  }, [gameState, obstacles, playerEffects, gameOver]);

  // helper to calculate pixel position
  function tileToPx(col, row) {
    return { left: col * TILE_SIZE, top: row * TILE_SIZE };
  }

  // Render
  return (
    <div className="w-full flex flex-col items-center gap-4 p-4 bg-gradient-to-b from-blue-100 to-green-100 min-h-screen">
      {/* Header */}
      <div className="flex items-center justify-between w-full max-w-[600px]">
        <div className="text-xl font-bold text-gray-800">🐔 Chicken Road</div>
        <div className="flex gap-3 items-center">
          <div className="text-sm bg-white px-2 py-1 rounded shadow">Score: <span className="font-bold text-blue-600">{score}</span></div>
          <div className="text-sm bg-white px-2 py-1 rounded shadow">Coins: <span className="font-bold text-yellow-600">{coins}</span></div>
          {gameState === GAME_STATE_PLAYING && (
            <button className="px-3 py-1 rounded bg-orange-500 text-white text-sm hover:bg-orange-600 transition-colors" onClick={togglePause}>
              Pause
            </button>
          )}
          {gameState === GAME_STATE_PAUSED && (
            <button className="px-3 py-1 rounded bg-green-500 text-white text-sm hover:bg-green-600 transition-colors" onClick={togglePause}>
              Resume
            </button>
          )}
          {gameState !== GAME_STATE_MENU && (
            <button className="px-3 py-1 rounded border border-gray-300 text-sm hover:bg-gray-50 transition-colors" onClick={restart}>
              Restart
            </button>
          )}
        </div>
      </div>

      {/* Power-up indicators */}
      {gameState === GAME_STATE_PLAYING && (
        <div className="flex gap-2 items-center">
          {playerEffects.shielded && (
            <div className="bg-blue-500 text-white px-2 py-1 rounded text-xs font-bold animate-pulse">
              🛡️ Shield Active
            </div>
          )}
          {playerEffects.speedBoost && (
            <div className="bg-red-500 text-white px-2 py-1 rounded text-xs font-bold animate-pulse">
              ⚡ Speed Boost
            </div>
          )}
          {playerEffects.magnetActive && (
            <div className="bg-purple-500 text-white px-2 py-1 rounded text-xs font-bold animate-pulse">
              🧲 Magnet Active
            </div>
          )}
        </div>
      )}

      <div
        ref={containerRef}
        className="relative bg-slate-100 shadow-lg rounded-lg overflow-hidden"
        style={{ width: COLUMNS * TILE_SIZE, height: ROWS * TILE_SIZE }}
      >
        {/* Lanes and background */}
        {LANES.map((lane, r) => (
          <div
            key={r}
            className="absolute left-0 right-0"
            style={{ top: r * TILE_SIZE, height: TILE_SIZE }}
          >
            <div className={`w-full h-full flex items-center`}>
              {lane.type === LANE_SAFE && (
                <div className="w-full h-full bg-green-200 border-t border-b border-green-300" />
              )}
              {lane.type === LANE_ROAD && (
                <div className="w-full h-full bg-slate-400/90 border-t border-b border-slate-500 relative">
                  {/* road markings */}
                  <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                    <div className="w-full h-1/2 flex items-center justify-between px-2">
                      {Array.from({ length: COLUMNS }).map((_, i) => (
                        <div key={i} className="w-[2px] h-2 bg-yellow-200/60" />
                      ))}
                    </div>
                  </div>
                </div>
              )}
              {lane.type === LANE_RIVER && (
                <div className="w-full h-full bg-blue-400 relative border-t border-b border-blue-600/60" />
              )}
            </div>
          </div>
        ))}

        {/* Obstacles */}
        {obstacles.map((laneObs, r) => (
          <React.Fragment key={`obs-${r}`}>
            {laneObs.map((o, i) => {
              const px = tileToPx(o.x, r);
              const w = (o.width || 1) * TILE_SIZE;
              const isRoad = LANES[r].type === LANE_ROAD;
              const isRiver = LANES[r].type === LANE_RIVER;
              return (
                <div
                  key={`${r}-${i}`}
                  className={`absolute top-0`}
                  style={{ left: px.left, top: r * TILE_SIZE + 6, width: w, height: TILE_SIZE - 12 }}
                >
                  <div className={`h-full rounded ${isRoad ? "bg-red-600 shadow-md" : "bg-yellow-700/90 rounded-md shadow-inner"} flex items-center justify-center text-xs text-white`}
                    title={`${isRoad ? 'Car' : 'Log'} (lane ${r})`}>
                    {isRoad ? "CAR" : "LOG"}
                  </div>
                </div>
              );
            })}
          </React.Fragment>
        ))}

        {/* Player */}
        <div
          className={`absolute transition-all duration-75 ease-linear`}
          style={{
            width: TILE_SIZE - 8,
            height: TILE_SIZE - 8,
            left: player.col * TILE_SIZE + 4,
            top: player.row * TILE_SIZE + 4,
            zIndex: 40
          }}
        >
          <div className="w-full h-full rounded-full bg-yellow-300 flex items-center justify-center text-sm font-bold shadow-inner border-2 border-yellow-500">🐔</div>
        </div>

        {/* Game over overlay */}
        {gameOver && (
          <div className="absolute inset-0 bg-black/50 z-50 flex items-center justify-center">
            <div className="bg-white p-6 rounded-lg shadow-lg text-center w-72">
              <h3 className="text-2xl font-bold mb-2">Game Over</h3>
              <p className="mb-4">Score: <span className="font-bold">{score}</span></p>
              <div className="flex gap-3 justify-center">
                <button className="px-4 py-2 rounded bg-red-600 text-white" onClick={restart}>Play Again</button>
                <button className="px-4 py-2 rounded border" onClick={() => { setGameOver(false); setIsRunning(false); }}>Close</button>
              </div>
            </div>
          </div>
        )}

      </div>

      {/* Touch controls (mobile) */}
      <div className="flex gap-3 items-center mt-2">
        <div className="grid grid-cols-3 gap-1">
          <button onClick={() => handleTouchMove('up')} className="px-3 py-2 rounded bg-slate-200">▲</button>
          <div />
          <button onClick={() => handleTouchMove('up')} className="px-3 py-2 rounded bg-slate-200">▲</button>
          <button onClick={() => handleTouchMove('left')} className="px-3 py-2 rounded bg-slate-200">◀</button>
          <button onClick={() => handleTouchMove('down')} className="px-3 py-2 rounded bg-slate-200">▼</button>
          <button onClick={() => handleTouchMove('right')} className="px-3 py-2 rounded bg-slate-200">▶</button>
        </div>
        <div className="text-sm text-slate-600">Use arrow keys or touch buttons. Tap tiles to move quickly.</div>
      </div>

      <div className="text-xs text-slate-500 mt-2 max-w-[520px]">Notes: This is a compact demo — tweak <code>LANES</code>, <code>speed</code>, and <code>density</code> to tune difficulty. For production, extract components, add sprites and sounds, and polish collisions & spawning.</div>
    </div>
  );
}
